  'accel (m/s²) and gyro (rad/s)': 'Beschleunigung (m/s²) und Gyro (rad/s)',
  'Accelerometer and gyroscope tiles': 'Kacheln für Beschleunigung und Gyroskop',
  'battery': 'battery',
